const CACHE='bunny-assets-v105',META='bunny-assets-meta-v105';
self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.origin!==location.origin||e.request.method!=='GET'||!/\.(png|jpe?g|webp|svg|gif|mp3|ogg|wav|mp4|webm|woff2?|glb|gltf|json)$/i.test(u.pathname)||u.pathname==='/preload-manifest.json')return;e.respondWith(caches.open(CACHE).then(async c=>{const cached=await c.match(u.pathname);if(!cached)return fetch(e.request);const range=e.request.headers.get('range');if(!range)return cached;const m=/^bytes=(\d*)-(\d*)$/.exec(range);if(!m)return fetch(e.request);const blob=await cached.blob(),start=m[1]?Number(m[1]):Math.max(0,blob.size-Number(m[2])),end=m[1]&&m[2]?Math.min(Number(m[2]),blob.size-1):blob.size-1;if(start>=blob.size||end<start)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+blob.size}});return new Response(blob.slice(start,end+1),{status:206,headers:{'Content-Type':cached.headers.get('Content-Type')||'application/octet-stream','Accept-Ranges':'bytes','Content-Range':'bytes '+start+'-'+end+'/'+blob.size,'Content-Length':String(end-start+1)}})}))});
self.addEventListener('message',e=>{if(e.data?.type!=='preload-all')return;const port=e.ports[0];e.waitUntil((async()=>{try{const m=await(await fetch('/preload-manifest.json',{cache:'no-store'})).json(),cache=await caches.open(CACHE),meta=await caches.open(META);let index=0,done=0,bytes=0;const fail=[];await Promise.all(Array.from({length:4},async()=>{for(;;){const f=m.files[index++];if(!f)return;try{const marker=await meta.match(f.url),hash=marker&&await marker.text();if(hash!==f.hash||!await cache.match(f.url)){const r=await fetch(f.url,{cache:'reload'});if(!r.ok)throw Error('HTTP '+r.status);await cache.put(f.url,r);await meta.put(f.url,new Response(f.hash))}}catch(error){fail.push(f.url)}done++;bytes+=f.bytes;port.postMessage({type:'progress',done,total:m.files.length,bytes,totalBytes:m.bytes})}}));port.postMessage({type:'done',failed:fail,total:m.files.length,version:m.version})}catch(error){port.postMessage({type:'error',message:String(error)})}})())});
